Make a project for this html file: Llanero Snake

<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>Llaneros Snake: The Chigüiro Chase</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Rye&family=Roboto:wght@400;700&display=swap');

        body {
            margin: 0;
            padding: 0;
            background-color: #2c3e50;
            color: white;
            font-family: 'Roboto', sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            overflow: hidden;
            touch-action: none; /* Prevent pull-to-refresh on mobile */
        }

        h1 {
            font-family: 'Rye', serif; /* Western/Rustic style */
            color: #f1c40f;
            text-shadow: 2px 2px #d35400;
            margin-bottom: 10px;
            text-align: center;
            font-size: 1.5rem;
        }

        #game-container {
            position: relative;
            box-shadow: 0 0 20px rgba(0,0,0,0.5);
            border: 8px solid #8d6e63; /* Wood border */
            border-radius: 4px;
            background: linear-gradient(to bottom, #4CA1AF, #C4E0E5); /* Sky fallback */
            /* Ensure container respects flex layout */
            display: flex;
            flex-direction: column;
        }

        canvas {
            display: block;
            background-color: #81C784; /* Grass base */
            max-width: 100%;
            /* height handled by JS */
        }

        #ui-layer {
            position: absolute;
            top: 10px;
            left: 0;
            width: 100%;
            display: flex;
            justify-content: space-between;
            padding: 0 20px;
            box-sizing: border-box;
            pointer-events: none;
            font-weight: bold;
            text-shadow: 1px 1px 2px black;
            font-size: 1.2rem;
            z-index: 5;
        }

        .p1-score { color: #DA70D6; } /* Orchid (Default P1 in single player) */
        .p2-score { color: #FFD700; } 

        #menu-overlay, #settings-overlay {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.85);
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            z-index: 10;
            padding: 20px;
            box-sizing: border-box;
        }

        #settings-overlay {
            z-index: 11; /* Above menu */
            display: none;
        }

        .btn-group {
            display: flex;
            gap: 20px;
            margin-top: 20px;
        }

        .btn {
            background: #e67e22;
            color: white;
            border: none;
            padding: 15px 30px;
            font-size: 1.2rem;
            font-family: 'Rye', serif;
            cursor: pointer;
            border-radius: 5px;
            transition: transform 0.1s, background 0.2s;
            border: 2px solid #d35400;
        }

        .btn:hover {
            background: #d35400;
            transform: scale(1.05);
        }

        .btn-secondary {
            background: #7f8c8d;
            color: white;
            border: none;
            padding: 10px 20px;
            font-size: 1rem;
            font-family: 'Roboto', sans-serif;
            cursor: pointer;
            border-radius: 5px;
            margin-top: 15px;
            border: 2px solid #95a5a6;
        }
        .btn-secondary:hover {
            background: #95a5a6;
        }

        .controls {
            margin-top: 20px;
            display: flex;
            gap: 40px;
            text-align: center;
        }

        .control-box {
            background: rgba(255,255,255,0.1);
            padding: 15px;
            border-radius: 8px;
        }

        .key {
            display: inline-block;
            background: #eee;
            color: #333;
            padding: 5px 10px;
            border-radius: 4px;
            font-weight: bold;
            font-size: 0.9rem;
            box-shadow: 0 2px 0 #bbb;
            margin: 2px;
        }

        #game-over-msg {
            font-size: 2rem;
            color: #e74c3c;
            margin-bottom: 20px;
            font-family: 'Rye', serif;
            text-align: center;
        }

        #winner-msg {
            color: #2ecc71;
            font-size: 1.5rem;
            margin-bottom: 20px;
        }

        #controls-info-text {
            color: #bbb;
            margin-top: 10px;
            font-size: 0.9rem;
            font-style: italic;
        }

        /* Joystick Styles */
        #joystick-container {
            position: absolute;
            bottom: 40px;
            left: 40px;
            width: 120px;
            height: 120px;
            background: rgba(255, 255, 255, 0.1);
            border: 2px solid rgba(255, 255, 255, 0.3);
            border-radius: 50%;
            touch-action: none;
            display: none; /* Hidden by default */
            z-index: 5;
            /* Arrow indicators background */
            background-image: 
                linear-gradient(to bottom, transparent 48%, rgba(255,255,255,0.2) 48%, rgba(255,255,255,0.2) 52%, transparent 52%),
                linear-gradient(to right, transparent 48%, rgba(255,255,255,0.2) 48%, rgba(255,255,255,0.2) 52%, transparent 52%);
        }

        #joystick-knob {
            position: absolute;
            top: 50%;
            left: 50%;
            width: 50px;
            height: 50px;
            background: rgba(255, 215, 0, 0.6); /* Gold semi-transparent */
            border-radius: 50%;
            transform: translate(-50%, -50%);
            pointer-events: none;
            box-shadow: 0 0 10px rgba(0,0,0,0.5);
            border: 2px solid #d35400;
        }

        /* Settings Styles */
        .setting-row {
            margin: 15px 0;
            display: flex;
            align-items: center;
            gap: 10px;
            font-size: 1.2rem;
            width: 100%;
            justify-content: center;
        }

        select {
            padding: 5px 10px;
            font-size: 1rem;
            border-radius: 5px;
            background: #eee;
            border: none;
            font-family: 'Roboto', sans-serif;
        }

        input[type=checkbox] {
            transform: scale(1.5);
        }

        /* Mobile adjustments */
        @media (max-width: 768px) {
            body {
                justify-content: flex-start;
                padding-top: 10px;
            }

            h1 { font-size: 1.2rem; margin-bottom: 5px; }

            .controls { display: none; }
            #mobile-hint { display: block !important; color: #81C784; margin-top: 10px; font-style: italic;}
            .btn { padding: 10px 20px; font-size: 1rem; }

            #game-container { 
                border-width: 4px; 
                /* Create space at the bottom for controls */
                padding-bottom: 140px; 
                background-color: #2c3e50; /* Dark background for controls area */
            }

            /* Joystick positioned in the padded area */
            #joystick-container {
                bottom: 10px;
                left: 50%;
                transform: translateX(-50%); /* Center joystick */
            }

            /* Hide 2 Player option and Keyboard Swap on mobile */
            #btn-2p, #swap-btn {
                display: none;
            }
        }
    </style>
</head>
<body>

    <h1>Llaneros Snake: The Chigüiro Chase 🇨🇴</h1>

    <div id="game-container">
        <div id="ui-layer">
            <div class="p1-score" id="score1-container">P1: <span id="score1">0</span></div>
            <div class="p2-score" id="score2-container">P2: <span id="score2">0</span></div>
        </div>

        <!-- Settings Overlay -->
        <div id="settings-overlay">
            <h2 id="settings-title" style="font-family:'Rye', serif; color: #f1c40f;">Settings</h2>

            <div class="setting-row">
                <label for="lang-select">Language / Idioma:</label>
                <select id="lang-select" onchange="changeLanguage()">
                    <option value="es" selected>Llaneros (Español)</option>
                    <option value="en">Gringos (English)</option>
                </select>
            </div>

            <div class="setting-row">
                <input type="checkbox" id="joystick-toggle" onchange="toggleJoystickSetting()">
                <label id="joystick-label" for="joystick-toggle">Enable Virtual Joystick</label>
            </div>

            <div class="setting-row">
                <input type="checkbox" id="bomb-toggle" onchange="toggleBombSetting()">
                <label id="bomb-label" for="bomb-toggle">Enable Bombs</label>
            </div>

            <div class="setting-row">
                <label id="diff-label" for="difficulty-select">Difficulty:</label>
                <select id="difficulty-select" onchange="setDifficulty()">
                    <option value="easy" id="opt-easy">Easy (Slow)</option>
                    <option value="medium" id="opt-medium" selected>Medium</option>
                    <option value="hard" id="opt-hard">Hard (Fast)</option>
                </select>
            </div>

            <p id="mobile-settings-hint" style="font-size:0.9rem; color:#ccc; max-width:300px; text-align:center;">
                Joystick Setting applies only to Mobile.
            </p>

            <button id="settings-close-btn" class="btn-secondary" onclick="closeSettings()">Close</button>
        </div>

        <!-- Main Menu Overlay -->
        <div id="menu-overlay">
            <h2 id="menu-title" style="font-family:'Rye', serif; color: #f1c40f; font-size: 3rem; margin:0;">¡Vamonos!</h2>
            <p id="menu-subtitle" style="color: #ccc;">Collect the Chigüiros within the Llanos.</p>

            <div id="game-over-content" style="display:none; text-align:center;">
                <div id="game-over-msg">GAME OVER</div>
                <div id="winner-msg"></div>
            </div>

            <div class="btn-group">
                <button id="btn-1p" class="btn" onclick="startGame(1)">1 Player<br><span style="font-size:0.8rem">(La Llanera)</span></button>
                <button id="btn-2p" class="btn" onclick="startGame(2)">2 Players<br><span style="font-size:0.8rem">(Pareja)</span></button>
            </div>

            <div style="display:flex; gap:10px; margin-top:15px;">
                <button id="swap-btn" class="btn-secondary" onclick="toggleControls()">⇄ Swap P2 Controls</button>
                <button id="settings-btn" class="btn-secondary" onclick="openSettings()">⚙️ Settings</button>
            </div>

            <div id="controls-info-text">1 Player Mode uses Arrows OR WASD</div>
            <div id="mobile-hint" style="display:none;">Swipe to control! 👆</div>

            <div class="controls" id="controls-display">
                <div class="control-box">
                    <div id="label-arrows" style="color: #FFD700; margin-bottom:5px;">Husband (P1)</div>
                    <span class="key">↑</span><br>
                    <span class="key">←</span><span class="key">↓</span><span class="key">→</span>
                </div>
                <div class="control-box">
                    <div id="label-wasd" style="color: #DA70D6; margin-bottom:5px;">Wife (P2)</div>
                    <span class="key">W</span><br>
                    <span class="key">A</span><span class="key">S</span><span class="key">D</span>
                </div>
            </div>
        </div>

        <canvas id="gameCanvas" width="800" height="600"></canvas>

        <!-- Virtual Joystick -->
        <div id="joystick-container">
            <div id="joystick-knob"></div>
        </div>
    </div>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        let score1El = document.getElementById('score1');
        let score2El = document.getElementById('score2');
        const score1Container = document.getElementById('score1-container');
        const score2Container = document.getElementById('score2-container');

        const menuOverlay = document.getElementById('menu-overlay');
        const settingsOverlay = document.getElementById('settings-overlay');
        const gameOverContent = document.getElementById('game-over-content');
        const winnerMsg = document.getElementById('winner-msg');

        const labelArrows = document.getElementById('label-arrows');
        const labelWasd = document.getElementById('label-wasd');
        const controlsDisplay = document.getElementById('controls-display');
        const swapBtn = document.getElementById('swap-btn');
        const controlsInfoText = document.getElementById('controls-info-text');
        const mobileHint = document.getElementById('mobile-hint');

        const joystickContainer = document.getElementById('joystick-container');
        const joystickKnob = document.getElementById('joystick-knob');
        const joystickToggle = document.getElementById('joystick-toggle');
        const bombToggle = document.getElementById('bomb-toggle');
        const difficultySelect = document.getElementById('difficulty-select');
        const langSelect = document.getElementById('lang-select');

        // Game Constants
        let TILE_SIZE = 20;
        let TILES_X = canvas.width / TILE_SIZE;
        let TILES_Y = canvas.height / TILE_SIZE;

        // Config
        const SPEEDS = {
            easy: 150,
            medium: 90,
            hard: 60
        };
        let currentDifficulty = 'medium';

        // Translations
        const TRANSLATIONS = {
            es: {
                menuTitle: "¡Vamonos!",
                menuSubtitle: "Recoge los Chigüiros en los Llanos.",
                btn1p: "1 Jugador<br><span style='font-size:0.8rem'>(La Llanera)</span>",
                btn2p: "2 Jugadores<br><span style='font-size:0.8rem'>(Pareja)</span>",
                swapBtn: "⇄ Cambiar Controles P2",
                settingsBtn: "⚙️ Configuración",
                controlsInfo: "Modo 1 Jugador usa Flechas O WASD",
                mobileSwipe: "¡Desliza para controlar! 👆",
                mobileJoy: "¡Usa la palanca! 🕹️",
                settingsTitle: "Configuración",
                joyLabel: "Activar Joystick Virtual",
                bombLabel: "Activar Bombas",
                diffLabel: "Dificultad:",
                optEasy: "Fácil (Lento)",
                optMedium: "Medio",
                optHard: "Difícil (Rápido)",
                mobSetHint: "La opción Joystick solo aplica en móvil.",
                closeBtn: "Cerrar",
                gameOver: "JUEGO TERMINADO",
                tie: "¡Choque Doble! ¡Empate!",
                winP1: "¡Ganó El Llanero (Esposo)!",
                winP2: "¡Ganó La Llanera (Esposa)!",
                win1P: "¡Puntaje: {score}! ¡Buen trabajo!",
                p1Label: "Esposo (P1)",
                p2Label: "Esposa (P2)"
            },
            en: {
                menuTitle: "Let's Go!",
                menuSubtitle: "Collect the Chigüiros within the Llanos.",
                btn1p: "1 Player<br><span style='font-size:0.8rem'>(La Llanera)</span>",
                btn2p: "2 Players<br><span style='font-size:0.8rem'>(Couple)</span>",
                swapBtn: "⇄ Swap P2 Controls",
                settingsBtn: "⚙️ Settings",
                controlsInfo: "1 Player Mode uses Arrows OR WASD",
                mobileSwipe: "Swipe to control! 👆",
                mobileJoy: "Use the joystick! 🕹️",
                settingsTitle: "Settings",
                joyLabel: "Enable Virtual Joystick",
                bombLabel: "Enable Bombs",
                diffLabel: "Difficulty:",
                optEasy: "Easy (Slow)",
                optMedium: "Medium",
                optHard: "Hard (Fast)",
                mobSetHint: "Joystick Setting applies only to Mobile.",
                closeBtn: "Close",
                gameOver: "GAME OVER",
                tie: "Double Crash! It's a Tie!",
                winP1: "El Llanero (Husband) Wins!",
                winP2: "La Llanera (Wife) Wins!",
                win1P: "Score: {score}! Great Job!",
                p1Label: "Husband (P1)",
                p2Label: "Wife (P2)"
            }
        };
        let currentLang = 'es';

        // Responsive Canvas
        function resizeCanvas() {
            if (window.innerWidth < 768) {
                // Mobile: Reduced height to allow for joystick padding
                canvas.width = window.innerWidth - 20; 
                canvas.height = window.innerHeight - 220; // Subtract header + padding
                // Minimum height guard
                if (canvas.height < 300) canvas.height = 300;
            } else {
                canvas.width = 800;
                canvas.height = 600;
            }

            TILE_SIZE = 20;
            canvas.width = Math.floor(canvas.width / TILE_SIZE) * TILE_SIZE;
            canvas.height = Math.floor(canvas.height / TILE_SIZE) * TILE_SIZE;

            TILES_X = canvas.width / TILE_SIZE;
            TILES_Y = canvas.height / TILE_SIZE;
        }
        window.addEventListener('resize', resizeCanvas);
        resizeCanvas(); 

        // State
        let gameLoopId;
        let isGameRunning = false;
        let controlsSwapped = false;
        let gameMode = 1; 
        let useJoystick = false;
        let bombsEnabled = false;

        // Game Objects
        let snake1 = {};
        let snake2 = {};
        let chiguiro = {};
        let aguacate = { active: false, x: 0, y: 0, timer: 0 };
        let bomb = { active: false, x: 0, y: 0, timer: 0 };
        let clouds = [];

        // Touch/Swipe State
        let touchStartX = 0;
        let touchStartY = 0;

        // --- LANGUAGE LOGIC ---
        function changeLanguage() {
            currentLang = langSelect.value;
            const t = TRANSLATIONS[currentLang];

            document.getElementById('menu-title').innerText = t.menuTitle;
            document.getElementById('menu-subtitle').innerText = t.menuSubtitle;
            document.getElementById('btn-1p').innerHTML = t.btn1p;
            document.getElementById('btn-2p').innerHTML = t.btn2p;
            document.getElementById('swap-btn').innerText = t.swapBtn;
            document.getElementById('settings-btn').innerText = t.settingsBtn;
            document.getElementById('controls-info-text').innerText = t.controlsInfo;

            // Mobile hint depends on mode
            if (useJoystick) mobileHint.innerText = t.mobileJoy;
            else mobileHint.innerText = t.mobileSwipe;

            document.getElementById('settings-title').innerText = t.settingsTitle;
            document.getElementById('joystick-label').innerText = t.joyLabel;
            document.getElementById('bomb-label').innerText = t.bombLabel;
            document.getElementById('diff-label').innerText = t.diffLabel;
            document.getElementById('opt-easy').innerText = t.optEasy;
            document.getElementById('opt-medium').innerText = t.optMedium;
            document.getElementById('opt-hard').innerText = t.optHard;
            document.getElementById('mobile-settings-hint').innerText = t.mobSetHint;
            document.getElementById('settings-close-btn').innerText = t.closeBtn;
            document.getElementById('game-over-msg').innerText = t.gameOver;

            updateControlLabels();
        }

        // --- SETTINGS LOGIC ---
        function openSettings() {
            settingsOverlay.style.display = 'flex';
        }

        function closeSettings() {
            settingsOverlay.style.display = 'none';
        }

        function toggleJoystickSetting() {
            useJoystick = joystickToggle.checked;
            const t = TRANSLATIONS[currentLang];
            if (useJoystick) {
                mobileHint.innerText = t.mobileJoy;
            } else {
                mobileHint.innerText = t.mobileSwipe;
            }
        }

        function toggleBombSetting() {
            bombsEnabled = bombToggle.checked;
        }

        function setDifficulty() {
            currentDifficulty = difficultySelect.value;
        }

        function toggleControls() {
            controlsSwapped = !controlsSwapped;
            updateControlLabels();
        }

        function updateControlLabels() {
             const t = TRANSLATIONS[currentLang];
             if (controlsSwapped) {
                labelArrows.innerText = t.p2Label;
                labelArrows.style.color = "#DA70D6"; 
                labelWasd.innerText = t.p1Label;
                labelWasd.style.color = "#FFD700"; 
            } else {
                labelArrows.innerText = t.p1Label;
                labelArrows.style.color = "#FFD700"; 
                labelWasd.innerText = t.p2Label;
                labelWasd.style.color = "#DA70D6"; 
            }
        }

        function initGame(mode) {
            gameMode = mode;
            aguacate.active = false;
            bomb.active = false;

            // Show/Hide Joystick based on setting
            if (useJoystick && window.innerWidth < 768) {
                joystickContainer.style.display = 'block';
            } else {
                joystickContainer.style.display = 'none';
            }

            if (gameMode === 1) {
                snake1 = {
                    body: [
                        {x: Math.floor(TILES_X/2), y: Math.floor(TILES_Y/2)},
                        {x: Math.floor(TILES_X/2)-1, y: Math.floor(TILES_Y/2)},
                        {x: Math.floor(TILES_X/2)-2, y: Math.floor(TILES_Y/2)}
                    ],
                    dx: 1, dy: 0, nextDx: 1, nextDy: 0,
                    score: 0,
                    colorType: 'orchid', 
                    name: "La Llanera",
                    dead: false
                };
                snake2 = { body: [], dead: true, score: 0 }; 
                score1Container.style.color = "#DA70D6";
                score1Container.innerHTML = `Score: <span id="score1">0</span>`;
                score2Container.style.display = 'none';
            } else {
                snake1 = {
                    body: [
                        {x: TILES_X - 5, y: Math.floor(TILES_Y/2)},
                        {x: TILES_X - 4, y: Math.floor(TILES_Y/2)},
                        {x: TILES_X - 3, y: Math.floor(TILES_Y/2)}
                    ],
                    dx: -1, dy: 0, nextDx: -1, nextDy: 0,
                    score: 0,
                    colorType: 'colombia',
                    name: "Tricolor (P1)",
                    dead: false
                };
                snake2 = {
                    body: [
                        {x: 4, y: Math.floor(TILES_Y/2)},
                        {x: 3, y: Math.floor(TILES_Y/2)},
                        {x: 2, y: Math.floor(TILES_Y/2)}
                    ],
                    dx: 1, dy: 0, nextDx: 1, nextDy: 0,
                    score: 0,
                    colorType: 'orchid',
                    name: "Orquídea (P2)",
                    dead: false
                };
                score1Container.style.color = "#FFD700";
                score1Container.innerHTML = `P1 (Tricolor): <span id="score1">0</span>`;
                score2Container.style.display = 'block';
                score2El.innerText = "0";
            }

            spawnChiguiro();
            generateClouds();

            score1El = document.getElementById('score1'); 
            if(gameMode === 2) score2El = document.getElementById('score2');

            score1El.innerText = "0";
            if(gameMode === 2) score2El.innerText = "0";

            gameOverContent.style.display = 'none';
        }

        function spawnChiguiro() {
            let valid = false;
            while(!valid) {
                let x = Math.floor(Math.random() * TILES_X);
                let y = Math.floor(Math.random() * TILES_Y);
                if(!isOccupied(x, y)) {
                    chiguiro = {x, y};
                    valid = true;
                }
            }
        }

        function spawnAguacate() {
            let valid = false;
            let attempts = 0;
            while(!valid && attempts < 50) {
                let x = Math.floor(Math.random() * TILES_X);
                let y = Math.floor(Math.random() * TILES_Y);
                if(!isOccupied(x, y) && (x !== chiguiro.x || y !== chiguiro.y) && (!bomb.active || (x !== bomb.x || y !== bomb.y))) {
                    aguacate = { active: true, x: x, y: y, timer: 60 };
                    valid = true;
                }
                attempts++;
            }
        }

        function spawnBomb() {
            let valid = false;
            let attempts = 0;
            while(!valid && attempts < 50) {
                let x = Math.floor(Math.random() * TILES_X);
                let y = Math.floor(Math.random() * TILES_Y);
                // Don't spawn on snakes, chiguiro, or aguacate
                if(!isOccupied(x, y) && 
                   (x !== chiguiro.x || y !== chiguiro.y) &&
                   (!aguacate.active || (x !== aguacate.x || y !== aguacate.y))) {
                    bomb = { active: true, x: x, y: y, timer: 150 }; // approx 15s at medium speed
                    valid = true;
                }
                attempts++;
            }
        }

        function isOccupied(x, y) {
            for(let part of snake1.body) if(part.x === x && part.y === y) return true;
            if(gameMode === 2 && snake2.body) {
                for(let part of snake2.body) if(part.x === x && part.y === y) return true;
            }
            return false;
        }

        function generateClouds() {
            clouds = [];
            for(let i=0; i<5; i++) {
                clouds.push({
                    x: Math.random() * canvas.width,
                    y: Math.random() * (canvas.height/2),
                    speed: 0.2 + Math.random() * 0.5,
                    size: 30 + Math.random() * 40
                });
            }
        }

        // --- INPUT HANDLING ---

        function setSnakeDirection(snake, dir) {
            if (dir === 'UP' && snake.dy === 0) { snake.nextDx = 0; snake.nextDy = -1; }
            if (dir === 'DOWN' && snake.dy === 0) { snake.nextDx = 0; snake.nextDy = 1; }
            if (dir === 'LEFT' && snake.dx === 0) { snake.nextDx = -1; snake.nextDy = 0; }
            if (dir === 'RIGHT' && snake.dx === 0) { snake.nextDx = 1; snake.nextDy = 0; }
        }

        // Keyboard
        document.addEventListener('keydown', (e) => {
            if(!isGameRunning) return;

            if (gameMode === 1) {
                if (e.key === 'ArrowUp' || e.key === 'w' || e.key === 'W') setSnakeDirection(snake1, 'UP');
                if (e.key === 'ArrowDown' || e.key === 's' || e.key === 'S') setSnakeDirection(snake1, 'DOWN');
                if (e.key === 'ArrowLeft' || e.key === 'a' || e.key === 'A') setSnakeDirection(snake1, 'LEFT');
                if (e.key === 'ArrowRight' || e.key === 'd' || e.key === 'D') setSnakeDirection(snake1, 'RIGHT');
            } else {
                const arrowSnake = controlsSwapped ? snake2 : snake1;
                const wasdSnake = controlsSwapped ? snake1 : snake2;

                if (e.key === 'ArrowUp') setSnakeDirection(arrowSnake, 'UP');
                if (e.key === 'ArrowDown') setSnakeDirection(arrowSnake, 'DOWN');
                if (e.key === 'ArrowLeft') setSnakeDirection(arrowSnake, 'LEFT');
                if (e.key === 'ArrowRight') setSnakeDirection(arrowSnake, 'RIGHT');

                if (e.key === 'w' || e.key === 'W') setSnakeDirection(wasdSnake, 'UP');
                if (e.key === 's' || e.key === 'S') setSnakeDirection(wasdSnake, 'DOWN');
                if (e.key === 'a' || e.key === 'A') setSnakeDirection(wasdSnake, 'LEFT');
                if (e.key === 'd' || e.key === 'D') setSnakeDirection(wasdSnake, 'RIGHT');
            }
        });

        // --- TOUCH HANDLING ---

        // 1. Global Swipe (Only if joystick disabled)
        document.addEventListener('touchstart', (e) => {
            if (!isGameRunning || useJoystick) return; // Ignore if joystick enabled
            touchStartX = e.touches[0].clientX;
            touchStartY = e.touches[0].clientY;
        }, { passive: false });

        document.addEventListener('touchmove', (e) => {
            if (!isGameRunning || useJoystick) return; // Ignore if joystick enabled
            e.preventDefault(); 

            let touchEndX = e.touches[0].clientX;
            let touchEndY = e.touches[0].clientY;

            let diffX = touchEndX - touchStartX;
            let diffY = touchEndY - touchStartY;

            const THRESHOLD = 20; 

            if (Math.abs(diffX) > THRESHOLD || Math.abs(diffY) > THRESHOLD) {
                let dir = '';
                if (Math.abs(diffX) > Math.abs(diffY)) {
                    dir = diffX > 0 ? 'RIGHT' : 'LEFT';
                } else {
                    dir = diffY > 0 ? 'DOWN' : 'UP';
                }
                setSnakeDirection(snake1, dir);
                touchStartX = touchEndX;
                touchStartY = touchEndY;
            }
        }, { passive: false });

        // 2. Virtual Joystick Logic
        let joystickActive = false;
        const maxDist = 35; 

        joystickContainer.addEventListener('touchstart', (e) => {
            if(!isGameRunning) return;
            e.preventDefault();
            joystickActive = true;
            updateJoystick(e.touches[0]);
        }, {passive: false});

        joystickContainer.addEventListener('touchmove', (e) => {
            if(!isGameRunning || !joystickActive) return;
            e.preventDefault();
            updateJoystick(e.touches[0]);
        }, {passive: false});

        joystickContainer.addEventListener('touchend', (e) => {
            e.preventDefault();
            joystickActive = false;
            // Reset visual
            joystickKnob.style.transform = `translate(-50%, -50%) translate(0px, 0px)`;
        });

        function updateJoystick(touch) {
            const rect = joystickContainer.getBoundingClientRect();
            const centerX = rect.left + rect.width / 2;
            const centerY = rect.top + rect.height / 2;

            const dx = touch.clientX - centerX;
            const dy = touch.clientY - centerY;

            const distance = Math.min(Math.hypot(dx, dy), maxDist);

            // Calculate Snap Direction
            let moveX = 0;
            let moveY = 0;
            let dir = '';

            // Simple quadrant check for 4-way snap
            if (Math.abs(dx) > Math.abs(dy)) {
                // Horizontal
                if (dx > 0) { dir = 'RIGHT'; moveX = distance; }
                else { dir = 'LEFT'; moveX = -distance; }
            } else {
                // Vertical
                if (dy > 0) { dir = 'DOWN'; moveY = distance; }
                else { dir = 'UP'; moveY = -distance; }
            }

            // Move Knob Visual (Snapped)
            joystickKnob.style.transform = `translate(-50%, -50%) translate(${moveX}px, ${moveY}px)`;

            if (distance > 10) { // Deadzone
                setSnakeDirection(snake1, dir);
            }
        }


        function startGame(mode) {
            initGame(mode);
            menuOverlay.style.display = 'none';
            isGameRunning = true;
            clearInterval(gameLoopId);
            gameLoopId = setInterval(gameLoop, SPEEDS[currentDifficulty]);
        }

        function gameLoop() {
            update();
            draw();

            if (gameMode === 1) {
                if(snake1.dead) endGame();
            } else {
                if(snake1.dead || snake2.dead) endGame();
            }
        }

        function update() {
            moveSnake(snake1);
            if(gameMode === 2) moveSnake(snake2);

            checkCollisions();

            // Aguacate Logic
            if(aguacate.active) {
                aguacate.timer--;
                if(aguacate.timer <= 0) aguacate.active = false;
            } else {
                if(Math.random() < 0.01) spawnAguacate();
            }

            // Bomb Logic
            if(bombsEnabled) {
                if(bomb.active) {
                    bomb.timer--;
                    if(bomb.timer <= 0) bomb.active = false;
                } else {
                    // Slight chance to spawn
                    if(Math.random() < 0.005) spawnBomb();
                }
            } else {
                bomb.active = false;
            }

            // Update clouds
            clouds.forEach(c => {
                c.x += c.speed;
                if(c.x > canvas.width) c.x = -c.size*2;
            });
        }

        function moveSnake(snake) {
            snake.dx = snake.nextDx;
            snake.dy = snake.nextDy;

            let newX = snake.body[0].x + snake.dx;
            let newY = snake.body[0].y + snake.dy;

            if (newX < 0) newX = TILES_X - 1;
            if (newX >= TILES_X) newX = 0;
            if (newY < 0) newY = TILES_Y - 1;
            if (newY >= TILES_Y) newY = 0;

            const head = { x: newX, y: newY };
            snake.body.unshift(head);

            // Collisions with objects
            if(head.x === chiguiro.x && head.y === chiguiro.y) {
                snake.score += 10;
                updateScores();
                spawnChiguiro();
            } 
            else if(aguacate.active && head.x === aguacate.x && head.y === aguacate.y) {
                snake.score += 50; 
                aguacate.active = false;
                updateScores();
            } 
            else if(bomb.active && head.x === bomb.x && head.y === bomb.y) {
                // Hit a bomb
                snake.dead = true;
            }
            else {
                snake.body.pop();
            }
        }

        function checkCollisions() {
            checkSelfCollision(snake1);
            if (gameMode === 2) {
                checkSelfCollision(snake2);
                for(let part of snake2.body) if(snake1.body[0].x === part.x && snake1.body[0].y === part.y) snake1.dead = true;
                for(let part of snake1.body) if(snake2.body[0].x === part.x && snake2.body[0].y === part.y) snake2.dead = true;
                if(snake1.body[0].x === snake2.body[0].x && snake1.body[0].y === snake2.body[0].y) {
                    snake1.dead = true;
                    snake2.dead = true;
                }
            }
        }

        function checkSelfCollision(snake) {
            const head = snake.body[0];
            for(let i = 1; i < snake.body.length; i++) {
                if(head.x === snake.body[i].x && head.y === snake.body[i].y) snake.dead = true;
            }
        }

        function updateScores() {
            score1El.innerText = snake1.score;
            if(gameMode === 2 && score2El) score2El.innerText = snake2.score;
        }

        function endGame() {
            isGameRunning = false;
            clearInterval(gameLoopId);

            const t = TRANSLATIONS[currentLang];
            let msg = "";
            if (gameMode === 1) {
                msg = t.win1P.replace("{score}", snake1.score);
            } else {
                if(snake1.dead && snake2.dead) msg = t.tie;
                else if(snake1.dead) msg = t.winP2;
                else msg = t.winP1;
            }

            winnerMsg.innerText = msg;
            gameOverContent.style.display = 'block';
            menuOverlay.style.display = 'flex';
            joystickContainer.style.display = 'none';
        }

        // --- DRAWING ---

        function draw() {
            drawBackground();
            drawChiguiroItem(chiguiro.x, chiguiro.y);
            if(aguacate.active) drawAguacate(aguacate.x, aguacate.y);
            if(bomb.active) drawBomb(bomb.x, bomb.y);
            drawSnake(snake1);
            if(gameMode === 2) drawSnake(snake2);
        }

        function drawBackground() {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            let grad = ctx.createLinearGradient(0, 0, 0, canvas.height);
            grad.addColorStop(0, "#4CA1AF");
            grad.addColorStop(1, "#C4E0E5");
            ctx.fillStyle = grad;
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.fillStyle = "rgba(255,255,255,0.6)";
            clouds.forEach(c => {
                ctx.beginPath();
                ctx.arc(c.x, c.y, c.size, 0, Math.PI * 2);
                ctx.arc(c.x + c.size*0.8, c.y - c.size*0.2, c.size*1.1, 0, Math.PI * 2);
                ctx.arc(c.x + c.size*1.6, c.y, c.size, 0, Math.PI * 2);
                ctx.fill();
            });

            ctx.fillStyle = "#66BB6A"; 
            ctx.fillRect(0, 0, canvas.width, canvas.height);
        }

        function drawChiguiroItem(x, y) {
            const px = x * TILE_SIZE;
            const py = y * TILE_SIZE;
            ctx.fillStyle = "#795548"; 
            ctx.beginPath();
            ctx.roundRect(px + 2, py + 5, 16, 10, 3);
            ctx.fill();
            ctx.beginPath();
            ctx.arc(px + 14, py + 8, 5, 0, Math.PI*2);
            ctx.fill();
            ctx.fillStyle = "#5D4037";
            ctx.beginPath();
            ctx.arc(px + 14, py + 4, 2, 0, Math.PI*2);
            ctx.fill();
            ctx.fillStyle = "black";
            ctx.beginPath();
            ctx.arc(px + 15, py + 7, 1, 0, Math.PI*2);
            ctx.fill();
        }

        function drawAguacate(x, y) {
            const px = x * TILE_SIZE;
            const py = y * TILE_SIZE;
            ctx.fillStyle = "#2E7D32";
            ctx.beginPath();
            ctx.ellipse(px + 10, py + 12, 7, 8, 0, 0, Math.PI * 2);
            ctx.ellipse(px + 10, py + 8, 5, 6, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = "#AED581";
            ctx.beginPath();
            ctx.ellipse(px + 10, py + 12, 5, 6, 0, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = "#5D4037";
            ctx.beginPath();
            ctx.arc(px + 10, py + 13, 3, 0, Math.PI * 2);
            ctx.fill();
        }

        function drawBomb(x, y) {
            const px = x * TILE_SIZE;
            const py = y * TILE_SIZE;

            // Bomb Body
            ctx.fillStyle = "black";
            ctx.beginPath();
            ctx.arc(px + 10, py + 12, 8, 0, Math.PI*2);
            ctx.fill();

            // Highlight
            ctx.fillStyle = "#555";
            ctx.beginPath();
            ctx.arc(px + 7, py + 9, 2, 0, Math.PI*2);
            ctx.fill();

            // Fuse
            ctx.strokeStyle = "#C0C0C0";
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(px + 10, py + 4);
            ctx.lineTo(px + 14, py - 2);
            ctx.stroke();

            // Spark
            ctx.fillStyle = "#FF5722";
            ctx.beginPath();
            ctx.arc(px + 14, py - 2, 2, 0, Math.PI*2);
            ctx.fill();
        }

        function drawSnake(snake) {
            snake.body.forEach((part, index) => {
                const px = part.x * TILE_SIZE;
                const py = part.y * TILE_SIZE;

                if(snake.colorType === 'colombia') {
                    let pattern = index % 4;
                    if(pattern <= 1) ctx.fillStyle = "#FFD700"; 
                    else if(pattern === 2) ctx.fillStyle = "#0033A0"; 
                    else ctx.fillStyle = "#CE1126"; 
                } else {
                    let pattern = index % 3;
                    if(pattern === 0) ctx.fillStyle = "#DA70D6"; 
                    else if(pattern === 1) ctx.fillStyle = "#9932CC"; 
                    else ctx.fillStyle = "#E6E6FA"; 
                }

                ctx.fillRect(px, py, TILE_SIZE, TILE_SIZE);
                ctx.strokeStyle = "rgba(0,0,0,0.2)";
                ctx.strokeRect(px, py, TILE_SIZE, TILE_SIZE);

                if(index === 0) {
                    ctx.fillStyle = "#D7CCC8"; 
                    ctx.beginPath();
                    ctx.ellipse(px + 10, py + 10, 8, 8, 0, 0, Math.PI * 2); 
                    ctx.fill();
                    ctx.fillStyle = "#3E2723"; 
                    ctx.beginPath();
                    ctx.arc(px + 10, py + 10, 4, 0, Math.PI * 2); 
                    ctx.fill();
                    ctx.fillStyle = "white";
                    ctx.beginPath();
                    ctx.arc(px + 7, py + 8, 2, 0, Math.PI*2);
                    ctx.arc(px + 13, py + 8, 2, 0, Math.PI*2);
                    ctx.fill();
                    ctx.fillStyle = "black";
                    ctx.beginPath();
                    ctx.arc(px + 7, py + 8, 1, 0, Math.PI*2);
                    ctx.arc(px + 13, py + 8, 1, 0, Math.PI*2);
                    ctx.fill();
                }
            });
        }

        drawBackground();
        // Apply default language (Spanish) on load
        changeLanguage();
    </script>
