  const handleAssetsLoaded = useCallback(() => {
      if (!mpState.active) return;
      if (mpState.role === 'none') return;

      // Update local status immediately
      setReadyStatus(prev => ({ ...prev, [mpState.role]: true }));

      const role = mpState.role;
      const sendReady = () => multiplayerService.send({ type: 'READY', payload: { role } as ReadyPacket });

      sendReady();
      setTimeout(sendReady, 100);
      setTimeout(sendReady, 200);
      setTimeout(sendReady, 400);

  }, [mpState]);

  // RE-READY LOGIC: Check if we are back in lobby with loaded assets (Rematch scenario)
  useEffect(() => {
      // If we are in lobby, MP is active, and assets are loaded, but we are marked not ready...
      if (showLobby && mpState.active && mpState.role !== 'none' && !readyStatus[mpState.role]) {
          // If we have local refs or basic urls, we are effectively ready
          // Since backgroundUrl state persists in App, this check is valid
          // We trigger the burst again to inform peer we are back
          if (backgroundUrl || settings.retroMode) {
              handleAssetsLoaded();
          }
      }
  }, [showLobby, mpState, readyStatus, backgroundUrl, settings.retroMode, handleAssetsLoaded]);

  const handleGameOver = useCallback((
