            <div className={`${settings.retroMode ? 'text-black bg-transparent' : 'text-orchid-500 bg-black/30'} px-2 rounded`} style={{ color: settings.retroMode ? 'black' : (gameMode === 1 ? '#DA70D6' : '#FFD700') }}>
                {gameMode === 2 ? 'P1: ' : 'P1: '}{scores.p1}
            </div>
