                        mpState={mpState}
                    />
                ) : showGameOver ? (
                    <GameOverMenu 
                        winnerText={winnerText}
                        narratorMessage={narratorMessage}
                        isLoadingCommentary={isLoadingCommentary}
                        duelStats={duelStats}
                        settings={settings}
                        startGame={startGame}
                        updateSetting={updateSetting}
                        setShowStats={setShowStats}
                        setShowSettings={setShowSettings}
                        isGeneratingAssets={isGeneratingAssets}
                        finalScore={scores.p1}
                        onOpenGastronomy={() => setShowGastronomy(true)}
                        mpState={mpState}
                        onCancelMultiplayer={cancelMultiplayer}
                        onRematch={handleRematchAction}
                    />
                ) : (
                    <MainMenu 
                        startGame={startGame}
                        startMultiplayerSetup={() => setShowLobby(true)}
                        settings={settings}
                        updateSetting={updateSetting}
                        setShowStats={setShowStats}
                        setShowSettings={setShowSettings}
                        isGeneratingAssets={isGeneratingAssets}
                    />
                )}
            </div>
        )}

        {/* Modals */}
        {showStats && <StatsModal stats={stats} onClose={() => setShowStats(false)} />}

        {showSettings && (
            <SettingsModal 
                settings={settings} 
                updateSetting={updateSetting} 
                onClose={() => setShowSettings(false)} 
            />
        )}

        {showGastronomy && (
            <GastronomyModal 
                items={sessionItems}
                onClose={() => setShowGastronomy(false)}
            />
        )}

      </div>
    </div>
  );
};

export default App;
